  "version": "v3",
  "description": "A robust background job queue system designed to handle at-least-once delivery, visibility timeouts, poison message management, and worker failures.",
  "dependencies": [
    {
      "name": "durable-queue-worker",
      "type": "library",
      "version": "~1.0"
    },
