// RekordyImport.js

const _ = require('lodash');

class RecordsImporter {
  constructor() {
    this.recs = [];
    this.lastCheckpoint = null;
    this.checkpointInterval = 500; // Checkpoints every 500ms
    this.isRunning = false;
    this.errorCount = 0;
  }

  async start(importer) {
    if (this.isRunning) return;

    this.isRunning = true;
    await importer.start();
    this.importer = importer;
    this.intervalId = setInterval(() => this.checkForDuplicates(), this.checkpointInterval);
  }

  stop() {
    clearInterval(this.intervalId);
    this.isRunning = false;
  }

  async checkForDuplicates() {
    const currentRecs = _.cloneDeep(this.recs);

    for (let i = 0; i < currentRecs.length - 1; i++) {
      for (let j = i + 1; j < currentRecs.length; j++) {
        if (_.isEqual(currentRecs[i], currentRecs[j])) {
          this.errorCount++;
          console.log(`Duplicate record found: ${currentRecs[i]}`);
          break;
        }
      }
    }

    if (this.errorCount > 0 && !this.lastCheckpoint) {
      this.lastCheckpoint = Date.now();
      console.log(`Checkpoint at ${new Date().toLocaleTimeString()} with error count ${this.errorCount}`);
    } else if (this.errorCount === 0 && this.lastCheckpoint !== null) {
      this.stop();
      console.log(`No duplicates detected since last checkpoint at ${new Date(this.lastCheckpoint).toLocaleTimeString()}.`);
    }

    this.errorCount = 0;
  }
}

module.exports = RecordsImporter;
